-- Robotics/Embedded/IoT pathway ("Vector Division") Act 8 -- "Sensors"
-- content, under world-vec-sensors (already inserted separately, under
-- act-vec-2, index 7). 1 campaign, 2 operations, 12 missions (11 lessons +
-- boss), following the same campaigns -> operations -> missions ->
-- dialogue -> objectives -> challenges -> hints pattern as every prior
-- Act. No new ChallengeType needed -- reuses story_dialogue,
-- multiple_choice, drag_and_drop, investigation, interactive_diagram,
-- browser_simulation (generic console fallback) and boss_encounter. With
-- two-way communication finally working (Act 7's close), Vector Division
-- pulls its first full sensor sweep off the live door and finds one
-- reading that does not match physical reality. Tomas and Byte build up
-- sensor fundamentals, temperature/light/distance sensors, the IMU trio
-- (accelerometer, gyroscope, magnetometer), calibration, noise/filtering
-- and sensor fusion intuition, before the boss mission proves the
-- mismatched reading -- PROX-19, an infrared proximity sensor -- is
-- neither malicious nor broken, only decades out of calibration, closing
-- into Act 9's actuators.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-vec-sensors', 'world-vec-sensors', 'sensors', '2C - Sensors', 'Learn the vocabulary of sensing itself -- sensor fundamentals, temperature, light and distance sensors, IMU concepts, the accelerometer, gyroscope and magnetometer, calibration, noise and filtering, and sensor fusion intuition -- while Vector Division proves that the door''s one impossible reading is neither malicious nor broken, just badly out of calibration.', 7);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-vec-sensors-1', 'campaign-vec-sensors', 'the-first-sweep', 'The First Sweep', 'Sensor fundamentals, temperature sensors, light sensors, distance sensors, IMU concepts, and the accelerometer.', 1),
  ('operation-vec-sensors-2', 'campaign-vec-sensors', 'the-reading-that-does-not-match', 'The Reading That Does Not Match', 'Gyroscope, magnetometer, calibration, noise and filtering, sensor fusion intuition, and the lying sensor itself.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-vec-sensors-01', 'world-vec-sensors', 'campaign-vec-sensors', 'operation-vec-sensors-1', 'sensor-fundamentals', 'Sensor Fundamentals', 'With two-way communication finally working, Vector Division pulls a full sensor sweep off the live door -- and one reading does not match physical reality at all. Imani sets the stakes; Tomas and Byte start with the most basic question of all: what a sensor actually is.', 'beginner', ARRAY['imani','tomas','byte'], null, null, '{"type":"simulation","simulationId":"sensor-fundamentals-sim"}'::jsonb, '{"xp":150,"credits":20}'::jsonb, false, 1),
  ('mission-vec-sensors-02', 'world-vec-sensors', 'campaign-vec-sensors', 'operation-vec-sensors-1', 'temperature-sensors', 'Temperature Sensors', 'Tomas begins cataloging the board''s sensors one family at a time, starting with temperature -- and the cabinet''s own thermal history turns out to matter more than the reading itself.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-sensors-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"temperature-sensors-sim"}'::jsonb, '{"xp":150,"credits":25}'::jsonb, false, 2),
  ('mission-vec-sensors-03', 'world-vec-sensors', 'campaign-vec-sensors', 'operation-vec-sensors-1', 'light-sensors', 'Light Sensors', 'A quick detour through light sensing rounds out the basic sensor vocabulary before the investigation turns toward the one sensor actually in question.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-sensors-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"light-sensors-sim"}'::jsonb, '{"xp":160,"credits":25}'::jsonb, false, 3),
  ('mission-vec-sensors-04', 'world-vec-sensors', 'campaign-vec-sensors', 'operation-vec-sensors-1', 'distance-sensors', 'Distance Sensors', 'The mismatched reading finally gets a name: PROX-19, an infrared proximity sensor that never measures centimeters directly -- it converts a raw measurement into distance through a calibration formula that could, in principle, be wrong.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-sensors-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"distance-sensors-sim"}'::jsonb, '{"xp":160,"credits":30}'::jsonb, false, 4),
  ('mission-vec-sensors-05', 'world-vec-sensors', 'campaign-vec-sensors', 'operation-vec-sensors-1', 'imu-concepts', 'IMU Concepts', 'Before diagnosing PROX-19 further, Byte introduces the IMU -- the bundled trio of sensors Vector Division will meet again on the door''s actuator systems, and the reason calibration and filtering matter for a whole set, not just one sensor.', 'beginner', ARRAY['byte','tomas'], '{"requiredMissionIds":["mission-vec-sensors-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"imu-concepts-sim"}'::jsonb, '{"xp":170,"credits":30}'::jsonb, false, 5),
  ('mission-vec-sensors-06', 'world-vec-sensors', 'campaign-vec-sensors', 'operation-vec-sensors-1', 'accelerometer', 'Accelerometer', 'The first IMU component: the accelerometer, and the constant, inescapable pull of gravity it can never read as zero.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-vec-sensors-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"accelerometer-sim"}'::jsonb, '{"xp":170,"credits":30}'::jsonb, false, 6),
  ('mission-vec-sensors-07', 'world-vec-sensors', 'campaign-vec-sensors', 'operation-vec-sensors-2', 'gyroscope', 'Gyroscope', 'The second IMU component: the gyroscope, and the quiet way a tiny constant bias becomes a large error the longer it is trusted.', 'beginner', ARRAY['byte','tomas'], '{"requiredMissionIds":["mission-vec-sensors-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"gyroscope-sim"}'::jsonb, '{"xp":180,"credits":35}'::jsonb, false, 7),
  ('mission-vec-sensors-08', 'world-vec-sensors', 'campaign-vec-sensors', 'operation-vec-sensors-2', 'magnetometer', 'Magnetometer', 'The third IMU component: the magnetometer, and the easiest of the set to fool with nothing more than a nearby motor.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-vec-sensors-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"magnetometer-sim"}'::jsonb, '{"xp":180,"credits":35}'::jsonb, false, 8),
  ('mission-vec-sensors-09', 'world-vec-sensors', 'campaign-vec-sensors', 'operation-vec-sensors-2', 'calibration', 'Calibration', 'Byte names the mechanism directly: calibration, the process every sensor on that board depends on and none of them get to skip forever.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-sensors-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"calibration-sim"}'::jsonb, '{"xp":190,"credits":35}'::jsonb, false, 9),
  ('mission-vec-sensors-10', 'world-vec-sensors', 'campaign-vec-sensors', 'operation-vec-sensors-2', 'noise-and-filtering', 'Noise and Filtering', 'PROX-19''s raw samples finally go under the microscope -- smooth, low-noise, and consistently wrong, which turns out to be the most important clue of all.', 'beginner', ARRAY['byte','tomas'], '{"requiredMissionIds":["mission-vec-sensors-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"noise-and-filtering-sim"}'::jsonb, '{"xp":190,"credits":40}'::jsonb, false, 10),
  ('mission-vec-sensors-11', 'world-vec-sensors', 'campaign-vec-sensors', 'operation-vec-sensors-2', 'sensor-fusion-intuition', 'Sensor Fusion Intuition', 'The last concept before the verdict: combining imperfect sensors so their errors do not simply stack, and what a disagreement between two sensors is actually trying to tell you.', 'beginner', ARRAY['byte','tomas'], '{"requiredMissionIds":["mission-vec-sensors-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"sensor-fusion-intuition-sim"}'::jsonb, '{"xp":200,"credits":40}'::jsonb, false, 11),
  ('mission-vec-sensors-12', 'world-vec-sensors', 'campaign-vec-sensors', 'operation-vec-sensors-2', 'the-lying-sensor', 'The Lying Sensor', 'Everything this Act taught, turned on one number: PROX-19''s. Not a hardware failure, not sabotage -- a sensor that was never recalibrated, reporting a wrong distance with total, unearned confidence.', 'boss', ARRAY['imani','tomas','byte'], '{"requiredMissionIds":["mission-vec-sensors-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"the-lying-sensor-boss-sim"}'::jsonb, '{"xp":750,"credits":160,"badgeIds":["the-lying-sensor"],"skillXp":{"robotics_fundamentals":95}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-vec-sensors-01', 1, 'imani', 'Two-way communication with the door is real now. Pull everything its sensors currently report -- every value, not just what the old firmware used to summarize for us.'),
  ('mission-vec-sensors-01', 2, 'byte', 'Sweep complete. Five readings: position, obstruction, ambient light, board temperature, and proximity to the nearest obstacle. Four of the five agree with what Tomas can verify standing right at the door.'),
  ('mission-vec-sensors-01', 3, 'tomas', 'The fifth does not agree with anything I can measure in front of it. Before we decide whether to trust or distrust that reading, we need the actual definition of what a sensor is, and is not.'),
  ('mission-vec-sensors-01', 4, 'tomas', 'A sensor is a transducer -- something that converts a physical quantity, like distance, temperature, or light, into an electrical signal a controller can read. It measures a fact. It does not judge that fact. A sensor reports a wrong number with exactly the same confidence as a right one.'),
  ('mission-vec-sensors-01', 5, 'byte', 'Which is the entire problem here. Nothing about the mismatched reading looks flagged, corrupted, or unusual. It looks like every other value on the sweep.'),
  ('mission-vec-sensors-01', 6, 'imani', 'Then treat it like every other value on the sweep, until you have an actual reason not to. Start with fundamentals.'),

  ('mission-vec-sensors-02', 1, 'tomas', 'Temperature sensors come in a few common flavors. A thermistor is a resistor whose resistance changes predictably with temperature. A thermocouple generates a small voltage directly from the junction of two different metals. Different physics, same job -- turn heat into a number.'),
  ('mission-vec-sensors-02', 2, 'tomas', 'The door''s board carries a thermistor bolted near the motor, and it reads exactly what a handheld thermometer confirms right now. Nothing wrong with it. But its maintenance log proves something else: this cabinet has swung through a real temperature range, for decades, with nobody opening it to check on anything inside.'),
  ('mission-vec-sensors-02', 3, 'byte', 'Every other sensor on that board has been living through those same swings the entire time. Worth remembering. It matters later.'),

  ('mission-vec-sensors-03', 1, 'tomas', 'Light sensors are simpler than people expect. A photoresistor changes resistance with light level -- more light, less resistance. A photodiode generates a small current directly, proportional to the light hitting it.'),
  ('mission-vec-sensors-03', 2, 'tomas', 'The door''s ambient light sensor is a photoresistor, wired to dim its status indicator at night. It has nothing to do with our mismatched reading. But it is proof this board mixes sensor types freely, whatever job each one needed.'),

  ('mission-vec-sensors-04', 1, 'tomas', 'Distance sensors measure how far away an object is, but almost none of them measure distance directly. An ultrasonic sensor times how long a sound pulse takes to bounce back. An infrared sensor often measures the angle or intensity of reflected light and converts that into a distance using a calibration curve baked in at the factory.'),
  ('mission-vec-sensors-04', 2, 'byte', 'Which is exactly what is fitted at the door. Its schematic labels it PROX-19, an infrared proximity sensor. It does not sense centimeters directly -- it senses reflected light intensity, then runs that number through a stored formula to report centimeters.'),
  ('mission-vec-sensors-04', 3, 'tomas', 'That is a distance sensor translating one quantity into another on a good day. If the formula it is running was ever wrong, the sensor would keep reporting a clean, confident number in centimeters. It would just be the wrong number.'),

  ('mission-vec-sensors-05', 1, 'byte', 'An IMU, an inertial measurement unit, is not one sensor. It is usually three: an accelerometer, a gyroscope, and often a magnetometer, packaged together and read as a set.'),
  ('mission-vec-sensors-05', 2, 'byte', 'Each one measures something different about motion and orientation, and none of them alone tells the whole story. That is exactly why they get bundled together -- and exactly why calibration and filtering, my territory, matter so much for the set as a whole.'),
  ('mission-vec-sensors-05', 3, 'tomas', 'The door itself does not carry a full IMU. But the actuator systems Vector Division meets later do, and the same reasoning applies to any sensor carrying an unearned assumption. Learn the pieces first.'),

  ('mission-vec-sensors-06', 1, 'byte', 'An accelerometer measures linear acceleration along one or more axes -- including the constant acceleration of gravity itself. Hold it still and it does not read zero. It reads roughly one g pointing straight down, always.'),
  ('mission-vec-sensors-06', 2, 'byte', 'Which means a stationary accelerometer can estimate tilt, just from how gravity splits across its axes. Move it, and that same reading becomes a mix of gravity and real motion, with no clean way to separate the two from a single instant alone.'),

  ('mission-vec-sensors-07', 1, 'byte', 'A gyroscope measures angular velocity -- how fast something is rotating right now, not what angle it is currently at.'),
  ('mission-vec-sensors-07', 2, 'byte', 'To get an angle, you have to integrate that rate over time, adding it up continuously. Any small, constant bias in the raw reading gets added up right along with it, and the estimated angle drifts further from reality the longer you let it run.'),
  ('mission-vec-sensors-07', 3, 'tomas', 'That is the same shape of problem as our mystery reading, just measured in degrees instead of centimeters. A tiny, constant error, trusted for a long time, becomes a large one.'),

  ('mission-vec-sensors-08', 1, 'byte', 'A magnetometer measures magnetic field strength and direction, most often used to estimate heading, like a compass.'),
  ('mission-vec-sensors-08', 2, 'byte', 'It is also the most easily fooled sensor in the set. Nearby metal, motors, and current-carrying wires all distort the field it is trying to measure -- distortions collectively called hard-iron and soft-iron effects. A magnetometer bolted next to a motor is reading a fantasy heading unless something corrects for that.'),

  ('mission-vec-sensors-09', 1, 'tomas', 'Calibration is comparing a sensor''s raw output against a known, trusted reference, and correcting for the difference. Two knobs usually do it: offset, a constant amount added or subtracted, and gain, a scale factor applied across the whole range.'),
  ('mission-vec-sensors-09', 2, 'tomas', 'A sensor calibrated once, at the factory, is only correct for the conditions it was calibrated under. Change the temperature enough, age the components enough, and the same raw signal starts meaning something slightly different than it used to.'),
  ('mission-vec-sensors-09', 3, 'byte', 'Which means an uncalibrated drift does not look like noise or a fault. It looks like a small, steady offset, present in every single reading, in the same direction, every time.'),
  ('mission-vec-sensors-09', 4, 'tomas', 'Keep that description in your head. We are about to need it.'),

  ('mission-vec-sensors-10', 1, 'byte', 'Every real sensor reading carries noise -- small, random fluctuation around the true value, different every time you sample it. Filtering, like a moving average or a low-pass filter, smooths that fluctuation out.'),
  ('mission-vec-sensors-10', 2, 'byte', 'But filtering cannot fix a bias. Average a hundred noisy samples that are all offset by the same 300 centimeters, and you get a beautifully smooth, low-noise number that is still wrong by 300 centimeters.'),
  ('mission-vec-sensors-10', 3, 'tomas', 'Which is exactly the tell. A broken sensor usually looks broken -- erratic, missing samples, wild swings. A miscalibrated sensor looks perfectly healthy. Smooth, stable, internally consistent. Just offset.'),

  ('mission-vec-sensors-11', 1, 'byte', 'Sensor fusion is not about picking the one best sensor. It is combining several imperfect sensors, each wrong in a different way, so their errors mostly cancel instead of stacking.'),
  ('mission-vec-sensors-11', 2, 'byte', 'A gyroscope is precise instantly but drifts over time. An accelerometer is stable over time but noisy instantly. Fuse them and the estimate inherits the strengths of both and the weaknesses of neither, for as long as both keep disagreeing in different directions.'),
  ('mission-vec-sensors-11', 3, 'tomas', 'Same idea applies even with only two sensors that were never designed to work together. If one distance reading looks wrong, and a second, independent sensor near the same spot reports something else, that disagreement alone is useful information -- as long as you never trust either one blindly.'),

  ('mission-vec-sensors-12', 1, 'imani', 'Time to answer the sweep for real. One sensor on that door does not match physical reality. Prove which one, prove why, and prove what actually needs to happen next.'),
  ('mission-vec-sensors-12', 2, 'tomas', 'PROX-19, the infrared proximity sensor. Distance sensors like this one do not measure centimeters directly -- they measure something else and convert it using a stored calibration formula. If that formula drifted, the sensor keeps reporting a clean, confident, wrong number.'),
  ('mission-vec-sensors-12', 3, 'byte', 'The raw samples back that up. Low noise, tight band, no erratic values, no missing samples -- nothing that looks like a hardware fault or an intrusion. Just a steady offset, present in every single reading, in the same direction, every time.'),
  ('mission-vec-sensors-12', 4, 'tomas', 'Decades in that cabinet, through every thermal swing the temperature sensor already proved happened, with nobody ever opening it to recalibrate anything. That is not malice. That is a sensor doing exactly what it was told, using numbers nobody has updated since it was installed.'),
  ('mission-vec-sensors-12', 5, 'imani', 'Then say the diagnosis plainly, and say what fixes it.'),
  ('mission-vec-sensors-12', 6, 'byte', 'Recalibrate it against a known reference, or cross-check it continuously against a second, independent sensor near the same spot -- either one turns an unearned, confident number back into a trustworthy one.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-vec-sensors-01-o1', 'mission-vec-sensors-01', 1, 'Read the sweep', 'Compare the sweep''s five readings against what Tomas can verify by hand, and find the one that does not match physical reality.'),
  ('mission-vec-sensors-01-o2', 'mission-vec-sensors-01', 2, 'Define a sensor', 'Choose the accurate definition of what a sensor actually is.'),

  ('mission-vec-sensors-02-o1', 'mission-vec-sensors-02', 1, 'Tell the sensor types apart', 'Match each temperature sensor description to its correct type.'),
  ('mission-vec-sensors-02-o2', 'mission-vec-sensors-02', 2, 'Read the thermal history', 'Find the evidence proving the board has experienced significant temperature swings over its lifetime.'),

  ('mission-vec-sensors-03-o1', 'mission-vec-sensors-03', 1, 'Tell the light sensor types apart', 'Sort each description into photoresistor or photodiode.'),

  ('mission-vec-sensors-04-o1', 'mission-vec-sensors-04', 1, 'Explain why a distance sensor can lie confidently', 'Choose the accurate reason an infrared distance sensor can report a wrong distance even when its raw measurement is healthy.'),
  ('mission-vec-sensors-04-o2', 'mission-vec-sensors-04', 2, 'Identify PROX-19', 'Find the evidence proving the mismatched reading in Mission 1 came from an infrared proximity sensor relying on a stored calibration formula.'),

  ('mission-vec-sensors-05-o1', 'mission-vec-sensors-05', 1, 'Define an IMU', 'Choose the accurate description of what an inertial measurement unit actually is.'),
  ('mission-vec-sensors-05-o2', 'mission-vec-sensors-05', 2, 'Match each component to what it measures', 'Match accelerometer, gyroscope and magnetometer to the physical quantity each one measures.'),

  ('mission-vec-sensors-06-o1', 'mission-vec-sensors-06', 1, 'Explain the gravity reading', 'Choose the accurate reason a stationary accelerometer never reads zero.'),
  ('mission-vec-sensors-06-o2', 'mission-vec-sensors-06', 2, 'Judge the tilt-estimation limit', 'Judge what happens to a tilt estimate the moment the accelerometer starts moving.'),

  ('mission-vec-sensors-07-o1', 'mission-vec-sensors-07', 1, 'Tell rate from angle', 'Choose the accurate description of what a gyroscope actually measures.'),
  ('mission-vec-sensors-07-o2', 'mission-vec-sensors-07', 2, 'Judge what integration does to bias', 'Judge what happens to a small, constant bias once it is integrated over time to estimate angle.'),

  ('mission-vec-sensors-08-o1', 'mission-vec-sensors-08', 1, 'Define what a magnetometer measures', 'Choose the accurate description of what a magnetometer measures and its most common use.'),
  ('mission-vec-sensors-08-o2', 'mission-vec-sensors-08', 2, 'Diagnose magnetic interference', 'Find the evidence showing a magnetometer reading is distorted by nearby magnetic interference rather than reporting true heading.'),

  ('mission-vec-sensors-09-o1', 'mission-vec-sensors-09', 1, 'Tell offset from gain', 'Choose the accurate distinction between offset and gain calibration.'),
  ('mission-vec-sensors-09-o2', 'mission-vec-sensors-09', 2, 'Recognize the drift signature', 'Given a description of a sensor''s misbehavior, judge whether it fits an uncalibrated drift, random noise, or a hardware fault.'),

  ('mission-vec-sensors-10-o1', 'mission-vec-sensors-10', 1, 'Tell noise from bias', 'Choose the accurate reason filtering smooths out noise but cannot correct a bias.'),
  ('mission-vec-sensors-10-o2', 'mission-vec-sensors-10', 2, 'Read PROX-19''s raw samples', 'Given PROX-19''s raw sample log, find the evidence showing its readings are smooth and internally consistent, not erratic or faulty.'),

  ('mission-vec-sensors-11-o1', 'mission-vec-sensors-11', 1, 'Explain the fusion intuition', 'Choose the accurate reason combining imperfect sensors beats relying on any single one.'),
  ('mission-vec-sensors-11-o2', 'mission-vec-sensors-11', 2, 'Propose a cross-check', 'Given two sensors that disagree about the same physical fact, judge the correct way to use that disagreement.'),

  ('mission-vec-sensors-12-o1', 'mission-vec-sensors-12', 1, 'Identify the liar', 'Given the schematic and calibration reasoning, judge which sensor is producing the false reading, and why.'),
  ('mission-vec-sensors-12-o2', 'mission-vec-sensors-12', 2, 'Prove it is drift, not damage', 'Find the evidence proving the mismatch is a calibration drift, not a hardware failure or sabotage.'),
  ('mission-vec-sensors-12-o3', 'mission-vec-sensors-12', 3, 'Propose the fix', 'Given everything learned this Act, choose the correct way to make the sensor trustworthy again.'),
  ('mission-vec-sensors-12-o4', 'mission-vec-sensors-12', 4, 'State the diagnosis', 'Having identified the liar, proven it is drift, and proposed the fix, state what the sensor actually is and what happens next.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-vec-sensors-01-o1-c1', 'mission-vec-sensors-01-o1', 1, 'investigation', 'Which reading from the sweep does not match physical reality?', '{"evidence":[{"id":"e1","label":"Position sensor","detail":"Reports OPEN, matching the door''s visibly open state"},{"id":"e2","label":"Board temperature","detail":"38 degrees Celsius, matching a handheld thermometer reading taken at the same spot"},{"id":"e3","label":"Ambient light sensor","detail":"Reports a dim reading, matching the installed light meter in the corridor"},{"id":"e4","label":"Proximity sensor","detail":"Reports 340 centimeters to the nearest obstacle, while Tomas, standing at the door with a tape measure, gets roughly 40 centimeters"}],"question":"Which reading from the sweep does not match physical reality?"}'::jsonb, '{"requiredEvidenceIds":["e4"]}'::jsonb),
  ('mission-vec-sensors-01-o2-c1', 'mission-vec-sensors-01-o2', 1, 'multiple_choice', 'A sensor is best defined as...', '{"question":"A sensor is best defined as...","options":[{"id":"a","text":"A device that decides what action a system should take"},{"id":"b","text":"A transducer that converts a physical quantity into an electrical signal, reporting a measurement without judging whether that measurement is correct"},{"id":"c","text":"A device that only ever measures electrical properties, never physical ones"},{"id":"d","text":"Any component that receives power from the main supply rail"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-sensors-02-o1-c1', 'mission-vec-sensors-02-o1', 1, 'drag_and_drop', 'Match each description to thermistor or thermocouple.', '{"items":[{"id":"i1","text":"A resistor whose resistance changes predictably as temperature changes"},{"id":"i2","text":"A voltage generated directly at the junction of two dissimilar metals, with no external excitation needed"},{"id":"i3","text":"A sensor whose resistance rises or falls smoothly with heat, requiring a small current from the circuit to read at all"},{"id":"i4","text":"A sensor that keeps producing a usable signal even without any power supplied to it at all"}],"targets":[{"id":"thermistor","label":"Thermistor"},{"id":"thermocouple","label":"Thermocouple"}]}'::jsonb, '{"correctMapping":{"i1":"thermistor","i2":"thermocouple","i3":"thermistor","i4":"thermocouple"}}'::jsonb),
  ('mission-vec-sensors-02-o2-c1', 'mission-vec-sensors-02-o2', 1, 'investigation', 'Which evidence proves the board has experienced significant temperature swings over its lifetime?', '{"evidence":[{"id":"e1","label":"Maintenance log","detail":"Cabinet interior temperature recorded between 5 and 55 degrees Celsius across three decades of seasonal readings"},{"id":"e2","label":"Access log","detail":"No entry recorded for this cabinet in the facility''s maintenance system in over twenty years"},{"id":"e3","label":"Power log","detail":"The board has drawn steady power from the same supply the entire time"}],"question":"Which evidence proves the board has experienced significant temperature swings over its lifetime?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-sensors-03-o1-c1', 'mission-vec-sensors-03-o1', 1, 'drag_and_drop', 'Sort each description into photoresistor or photodiode.', '{"items":[{"id":"i1","text":"Resistance drops as more light hits the sensor"},{"id":"i2","text":"Generates a small current directly, proportional to light intensity"},{"id":"i3","text":"Commonly used for a simple, cheap ambient-light or day/night reading"},{"id":"i4","text":"Commonly favored where a fast, precise light measurement is needed"}],"targets":[{"id":"photoresistor","label":"Photoresistor"},{"id":"photodiode","label":"Photodiode"}]}'::jsonb, '{"correctMapping":{"i1":"photoresistor","i2":"photodiode","i3":"photoresistor","i4":"photodiode"}}'::jsonb),

  ('mission-vec-sensors-04-o1-c1', 'mission-vec-sensors-04-o1', 1, 'multiple_choice', 'Why can an infrared distance sensor report a confidently wrong distance even if its raw measurement is perfectly healthy?', '{"question":"Why can an infrared distance sensor report a confidently wrong distance even if its raw measurement is perfectly healthy?","options":[{"id":"a","text":"It cannot -- infrared sensors always measure distance directly"},{"id":"b","text":"It converts a raw measurement, like reflected light intensity, into a distance using a stored calibration formula -- if that formula is wrong, the output is a clean, confident, wrong number"},{"id":"c","text":"Infrared sensors only fail when physically damaged"},{"id":"d","text":"The sensor reports raw voltage only, with no conversion involved at all"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-sensors-04-o2-c1', 'mission-vec-sensors-04-o2', 1, 'investigation', 'Which evidence proves the mismatched reading came from a sensor that converts its raw measurement into distance using a stored calibration formula?', '{"evidence":[{"id":"e1","label":"Sweep record","detail":"Sensor ID PROX-19 reported 340 centimeters during the sweep in question"},{"id":"e2","label":"Board schematic","detail":"PROX-19 is labeled an infrared proximity sensor that converts reflected light intensity into a distance using an onboard calibration table, not a direct distance measurement"},{"id":"e3","label":"Power log","detail":"PROX-19 draws a stable, expected current with no undervoltage events"}],"question":"Which evidence proves the mismatched reading came from a sensor that converts its raw measurement into distance using a stored calibration formula?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-vec-sensors-05-o1-c1', 'mission-vec-sensors-05-o1', 1, 'multiple_choice', 'An inertial measurement unit (IMU) is best described as...', '{"question":"An inertial measurement unit (IMU) is best described as...","options":[{"id":"a","text":"A single sensor that measures distance directly"},{"id":"b","text":"A bundle of separate sensors, typically an accelerometer, a gyroscope, and often a magnetometer, each measuring a different aspect of motion or orientation"},{"id":"c","text":"A type of distance sensor used only in robotics arms"},{"id":"d","text":"A single chip that replaces the need for calibration entirely"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-sensors-05-o2-c1', 'mission-vec-sensors-05-o2', 1, 'drag_and_drop', 'Match each IMU component to the physical quantity it measures.', '{"items":[{"id":"i1","text":"Accelerometer"},{"id":"i2","text":"Gyroscope"},{"id":"i3","text":"Magnetometer"}],"targets":[{"id":"t1","label":"Linear acceleration, including gravity"},{"id":"t2","label":"Angular velocity, the rate of rotation"},{"id":"t3","label":"Magnetic field strength and direction, often used for heading"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3"}}'::jsonb),

  ('mission-vec-sensors-06-o1-c1', 'mission-vec-sensors-06-o1', 1, 'multiple_choice', 'Why does a perfectly stationary accelerometer never read zero on all axes?', '{"question":"Why does a perfectly stationary accelerometer never read zero on all axes?","options":[{"id":"a","text":"It is always slightly miscalibrated from the factory"},{"id":"b","text":"It continuously measures the constant acceleration of gravity, roughly one g, splitting across its axes based on orientation"},{"id":"c","text":"Accelerometers cannot measure anything while stationary"},{"id":"d","text":"Zero readings are reserved for when the device is powered off"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-sensors-06-o2-c1', 'mission-vec-sensors-06-o2', 1, 'multiple_choice', 'An accelerometer is used to estimate tilt from how gravity splits across its axes. What happens to that estimate the instant the sensor starts moving?', '{"question":"An accelerometer is used to estimate tilt from how gravity splits across its axes. What happens to that estimate the instant the sensor starts moving?","options":[{"id":"a","text":"Nothing changes, motion has no effect on the reading"},{"id":"b","text":"The reading becomes a mix of gravity and real acceleration from the motion, with no way to cleanly separate the two from a single instantaneous reading"},{"id":"c","text":"The sensor automatically filters out the motion component on its own"},{"id":"d","text":"The tilt estimate becomes more accurate during motion"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-sensors-07-o1-c1', 'mission-vec-sensors-07-o1', 1, 'multiple_choice', 'A gyroscope directly measures...', '{"question":"A gyroscope directly measures...","options":[{"id":"a","text":"The current angle of the device relative to a fixed reference"},{"id":"b","text":"Angular velocity -- the rate of rotation right now, which must be integrated over time to estimate an angle"},{"id":"c","text":"Linear acceleration along a single axis"},{"id":"d","text":"Magnetic heading relative to north"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-sensors-07-o2-c1', 'mission-vec-sensors-07-o2', 1, 'multiple_choice', 'A gyroscope has a small, constant bias in its raw reading. What happens to the estimated angle once that reading is integrated continuously over a long period?', '{"question":"A gyroscope has a small, constant bias in its raw reading. What happens to the estimated angle once that reading is integrated continuously over a long period?","options":[{"id":"a","text":"The bias averages out to zero on its own"},{"id":"b","text":"The bias accumulates right along with the real rotation, so the estimated angle drifts further and further from reality the longer the integration runs"},{"id":"c","text":"The bias only affects the very first reading and then disappears"},{"id":"d","text":"Integration automatically corrects for any constant bias"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-sensors-08-o1-c1', 'mission-vec-sensors-08-o1', 1, 'multiple_choice', 'A magnetometer measures...', '{"question":"A magnetometer measures...","options":[{"id":"a","text":"Angular velocity, the same quantity as a gyroscope"},{"id":"b","text":"Magnetic field strength and direction, most commonly used to estimate heading"},{"id":"c","text":"Linear acceleration relative to gravity"},{"id":"d","text":"Ambient light intensity"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-sensors-08-o2-c1', 'mission-vec-sensors-08-o2', 1, 'investigation', 'Which evidence shows the magnetometer''s heading is distorted by nearby magnetic interference rather than reflecting true heading?', '{"evidence":[{"id":"e1","label":"Placement note","detail":"The magnetometer is mounted directly beside the door''s drive motor, within a few centimeters of its housing"},{"id":"e2","label":"Heading log","detail":"The magnetometer''s reported heading shifts by tens of degrees whenever the motor draws current, then returns to its prior reading once the motor stops"},{"id":"e3","label":"Power log","detail":"The magnetometer''s own supply voltage stays within normal range throughout"}],"question":"Which evidence shows the magnetometer''s heading is distorted by nearby magnetic interference rather than reflecting true heading?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-vec-sensors-09-o1-c1', 'mission-vec-sensors-09-o1', 1, 'multiple_choice', 'Offset and gain calibration differ in that...', '{"question":"Offset and gain calibration differ in that...","options":[{"id":"a","text":"They are two names for exactly the same correction"},{"id":"b","text":"Offset corrects a constant amount added or subtracted across every reading; gain corrects a scale factor applied across the whole measurement range"},{"id":"c","text":"Offset only applies to temperature sensors, gain only to distance sensors"},{"id":"d","text":"Gain is only relevant during manufacturing and never needs revisiting"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-sensors-09-o2-c1', 'mission-vec-sensors-09-o2', 1, 'multiple_choice', 'A sensor''s readings are smooth, low-variance, and consistently off by the same amount in the same direction every time, with nothing erratic or missing. What does that pattern fit?', '{"question":"A sensor''s readings are smooth, low-variance, and consistently off by the same amount in the same direction every time, with nothing erratic or missing. What does that pattern fit?","options":[{"id":"a","text":"A hardware fault, since the sensor is clearly broken"},{"id":"b","text":"An uncalibrated drift -- a steady, consistent offset is exactly the signature calibration correction is meant to fix, not the signature of noise or damage"},{"id":"c","text":"Random noise, since the readings vary at all"},{"id":"d","text":"Deliberate sabotage, since the values are clearly wrong"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-sensors-10-o1-c1', 'mission-vec-sensors-10-o1', 1, 'multiple_choice', 'Why can a filter like a moving average smooth out sensor noise but never correct a bias?', '{"question":"Why can a filter like a moving average smooth out sensor noise but never correct a bias?","options":[{"id":"a","text":"Filters can correct both equally well"},{"id":"b","text":"Noise is random fluctuation that partly cancels out when averaged; a bias shifts every single sample in the same direction, so averaging preserves the shift instead of removing it"},{"id":"c","text":"Bias only exists in digital sensors, never analog ones"},{"id":"d","text":"Filtering makes bias worse, never better"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-sensors-10-o2-c1', 'mission-vec-sensors-10-o2', 1, 'investigation', 'Which evidence shows PROX-19''s readings are smooth and internally consistent, not erratic or faulty, despite being wrong?', '{"evidence":[{"id":"e1","label":"Distractor note","detail":"PROX-19''s enclosure shows normal wear consistent with its age, no visible damage"},{"id":"e2","label":"Raw sample log","detail":"Twenty consecutive raw samples from PROX-19 all fall within a tight 320 to 345 centimeter band, low variance, no missing or erratic values -- while manual measurement at the same physical position confirms roughly 40 centimeters"},{"id":"e3","label":"Access log","detail":"No maintenance or network access has ever been recorded on the PROX-19 line"}],"question":"Which evidence shows PROX-19''s readings are smooth and internally consistent, not erratic or faulty, despite being wrong?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-vec-sensors-11-o1-c1', 'mission-vec-sensors-11-o1', 1, 'multiple_choice', 'Why does combining several imperfect sensors often beat relying on the single best one?', '{"question":"Why does combining several imperfect sensors often beat relying on the single best one?","options":[{"id":"a","text":"More sensors always means more accurate data, regardless of how each one fails"},{"id":"b","text":"Different sensors tend to be wrong in different ways, so combining them lets their individual errors cancel rather than stack, as long as they are not all wrong the same way at once"},{"id":"c","text":"Combining sensors eliminates the need for calibration entirely"},{"id":"d","text":"A single well-chosen sensor is always more reliable than any combination"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-sensors-11-o2-c1', 'mission-vec-sensors-11-o2', 1, 'multiple_choice', 'Two independent sensors near the same spot report different values for the same physical fact. What is the correct way to use that disagreement?', '{"question":"Two independent sensors near the same spot report different values for the same physical fact. What is the correct way to use that disagreement?","options":[{"id":"a","text":"Always trust whichever sensor reported first"},{"id":"b","text":"Treat the disagreement itself as useful information -- it signals that at least one sensor needs verification, rather than blindly trusting either reading alone"},{"id":"c","text":"Average the two values automatically with no further investigation"},{"id":"d","text":"Ignore both readings until a third sensor is installed"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-sensors-12-o1-c1', 'mission-vec-sensors-12-o1', 1, 'multiple_choice', 'Based on the schematic and everything learned about distance sensors and calibration, which sensor produced the false reading, and what kind of failure is it?', '{"question":"Based on the schematic and everything learned about distance sensors and calibration, which sensor produced the false reading, and what kind of failure is it?","options":[{"id":"a","text":"The magnetometer, distorted by the nearby drive motor"},{"id":"b","text":"PROX-19, the infrared proximity sensor, suffering an uncorrected calibration drift in its intensity-to-distance conversion"},{"id":"c","text":"The accelerometer, confusing gravity with real motion"},{"id":"d","text":"The board''s thermistor, malfunctioning from age"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-sensors-12-o2-c1', 'mission-vec-sensors-12-o2', 1, 'investigation', 'Which evidence proves the mismatch is a calibration drift rather than a hardware failure or sabotage?', '{"evidence":[{"id":"e1","label":"PROX-19 raw sample log","detail":"Twenty consecutive readings, low variance, no missing or erratic values, but every one measures roughly 300 centimeters higher than the confirmed physical distance"},{"id":"e2","label":"Access log","detail":"No maintenance or network access has ever been recorded on the PROX-19 line, ruling out tampering"},{"id":"e3","label":"Power log","detail":"PROX-19 draws a stable, expected current with no undervoltage events"}],"question":"Which evidence proves the mismatch is a calibration drift rather than a hardware failure or sabotage?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-vec-sensors-12-o3-c1', 'mission-vec-sensors-12-o3', 1, 'multiple_choice', 'Given everything learned this Act, what is the correct fix for PROX-19?', '{"question":"Given everything learned this Act, what is the correct fix for PROX-19?","options":[{"id":"a","text":"Replace the sensor outright without diagnosing the cause"},{"id":"b","text":"Recalibrate PROX-19 against a known reference distance, and cross-check it continuously against a second, independent sensor near the same spot so a future drift cannot go unnoticed again"},{"id":"c","text":"Ignore the reading, since the door still opens and closes correctly"},{"id":"d","text":"Disconnect the sensor permanently and rely on the position sensor alone forever"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-sensors-12-o4-c1', 'mission-vec-sensors-12-o4', 1, 'boss_encounter', 'Having identified the liar, proven it is drift, and proposed the fix, state what the sensor actually is and what happens next.', '{"stages":[{"objectiveRef":"mission-vec-sensors-12-o1","label":"Identify the liar"},{"objectiveRef":"mission-vec-sensors-12-o2","label":"Prove it is drift, not damage"},{"objectiveRef":"mission-vec-sensors-12-o3","label":"Propose the fix"}],"task":"State the diagnosis in one sentence: PROX-19 was never malicious and never broken -- it is a real proximity sensor that was never recalibrated after decades of thermal drift, reporting a plausible-looking but wrong distance with total, unearned confidence, the same danger as a confidently wrong answer from any other kind of system -- and a sensor that can be trusted, once calibrated and filtered, is only half the loop; the other half is whatever the door does in response, its actuators."}'::jsonb, '{"requiredObjectiveIds":["mission-vec-sensors-12-o1","mission-vec-sensors-12-o2","mission-vec-sensors-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-vec-sensors-01-o1-c1', 'orientation', 'Four of the five readings already match something Tomas can verify directly. Look for the one that does not.', 10, 1),
  ('mission-vec-sensors-01-o1-c1', 'solution', 'e4: the proximity sensor reports 340 centimeters while Tomas measures roughly 40 centimeters at the same spot -- the one reading that fails a direct physical check.', 20, 2),
  ('mission-vec-sensors-01-o2-c1', 'orientation', 'A sensor measures. It does not decide, and it does not act.', 10, 1),
  ('mission-vec-sensors-01-o2-c1', 'solution', 'A sensor is a transducer -- it converts a physical quantity into an electrical signal, and reports that measurement regardless of whether it happens to be correct.', 20, 2),

  ('mission-vec-sensors-02-o1-c1', 'orientation', 'One type changes resistance and needs a current to read. The other generates its own small voltage with no external power at all.', 10, 1),
  ('mission-vec-sensors-02-o1-c1', 'solution', 'Thermistor: i1 and i3, a resistor that changes with heat and needs current to read. Thermocouple: i2 and i4, a voltage generated directly at the junction with no external power needed.', 20, 2),
  ('mission-vec-sensors-02-o2-c1', 'orientation', 'Look for a log describing temperature over time, not access or power draw.', 10, 1),
  ('mission-vec-sensors-02-o2-c1', 'solution', 'e1: three decades of seasonal readings swinging between 5 and 55 degrees Celsius is direct proof of significant thermal swings.', 20, 2),

  ('mission-vec-sensors-03-o1-c1', 'orientation', 'One changes its resistance with light. The other generates a current directly.', 10, 1),
  ('mission-vec-sensors-03-o1-c1', 'solution', 'Photoresistor: i1 and i3, resistance-based and typically used for cheap ambient sensing. Photodiode: i2 and i4, current-based and used where speed and precision matter more.', 20, 2),

  ('mission-vec-sensors-04-o1-c1', 'orientation', 'Ask what an infrared sensor actually measures directly, versus what it reports.', 10, 1),
  ('mission-vec-sensors-04-o1-c1', 'solution', 'It measures something else, like reflected intensity, then converts that into distance with a stored formula -- a wrong formula produces a confidently wrong distance.', 20, 2),
  ('mission-vec-sensors-04-o2-c1', 'orientation', 'Look for the schematic entry describing how PROX-19 actually computes its number, not just its raw reading or its power draw.', 10, 1),
  ('mission-vec-sensors-04-o2-c1', 'solution', 'e2: the schematic confirms PROX-19 converts reflected intensity into distance through an onboard calibration table, exactly the kind of sensor that can lie confidently.', 20, 2),

  ('mission-vec-sensors-05-o1-c1', 'orientation', 'Think about whether an IMU is one sensor, or several bundled together.', 10, 1),
  ('mission-vec-sensors-05-o1-c1', 'solution', 'An IMU bundles multiple sensors -- typically accelerometer, gyroscope, and often magnetometer -- each covering a different piece of motion or orientation.', 20, 2),
  ('mission-vec-sensors-05-o2-c1', 'orientation', 'One measures straight-line motion, one measures rotation rate, one measures magnetic field.', 10, 1),
  ('mission-vec-sensors-05-o2-c1', 'solution', 'Accelerometer measures linear acceleration including gravity. Gyroscope measures angular velocity. Magnetometer measures magnetic field, often for heading.', 20, 2),

  ('mission-vec-sensors-06-o1-c1', 'orientation', 'Gravity does not turn off just because the sensor is not moving.', 10, 1),
  ('mission-vec-sensors-06-o1-c1', 'solution', 'A stationary accelerometer still measures gravity, roughly one g, distributed across its axes according to orientation.', 20, 2),
  ('mission-vec-sensors-06-o2-c1', 'orientation', 'A single instantaneous reading cannot tell you how much of it is gravity and how much is real movement.', 10, 1),
  ('mission-vec-sensors-06-o2-c1', 'solution', 'Moving the sensor mixes gravity and real acceleration into one reading, with no clean way to separate them from that instant alone.', 20, 2),

  ('mission-vec-sensors-07-o1-c1', 'orientation', 'Ask whether the raw output is an angle itself, or a rate that has to be accumulated into one.', 10, 1),
  ('mission-vec-sensors-07-o1-c1', 'solution', 'A gyroscope measures angular velocity directly; angle only comes from integrating that rate over time.', 20, 2),
  ('mission-vec-sensors-07-o2-c1', 'orientation', 'Adding the same small constant value over and over does not shrink -- it accumulates.', 10, 1),
  ('mission-vec-sensors-07-o2-c1', 'solution', 'A constant bias accumulates with every integration step, so the estimated angle drifts progressively further from the true value.', 20, 2),

  ('mission-vec-sensors-08-o1-c1', 'orientation', 'Think compass, not motion.', 10, 1),
  ('mission-vec-sensors-08-o1-c1', 'solution', 'A magnetometer measures magnetic field strength and direction, most commonly to estimate heading.', 20, 2),
  ('mission-vec-sensors-08-o2-c1', 'orientation', 'Look for a reading that changes with something unrelated to the device''s actual orientation.', 10, 1),
  ('mission-vec-sensors-08-o2-c1', 'solution', 'e2: the heading shifting with motor current and reverting once the motor stops is the signature of magnetic interference, not a true heading change.', 20, 2),

  ('mission-vec-sensors-09-o1-c1', 'orientation', 'One correction is a flat amount. The other is a multiplier across the whole range.', 10, 1),
  ('mission-vec-sensors-09-o1-c1', 'solution', 'Offset is a constant added or subtracted; gain is a scale factor applied across the whole range.', 20, 2),
  ('mission-vec-sensors-09-o2-c1', 'orientation', 'Ask whether the pattern is steady and one-directional, or erratic and unpredictable.', 10, 1),
  ('mission-vec-sensors-09-o2-c1', 'solution', 'A steady, one-directional offset with no erratic behavior fits an uncalibrated drift, not noise or a hardware fault.', 20, 2),

  ('mission-vec-sensors-10-o1-c1', 'orientation', 'Averaging cancels out values that go in different directions. A bias never changes direction.', 10, 1),
  ('mission-vec-sensors-10-o1-c1', 'solution', 'Noise is random and partly cancels when averaged; a bias shifts every sample the same way, so averaging preserves it instead of removing it.', 20, 2),
  ('mission-vec-sensors-10-o2-c1', 'orientation', 'Look for the log describing the shape of many samples together, not a single note about wear or access history.', 10, 1),
  ('mission-vec-sensors-10-o2-c1', 'solution', 'e2: twenty samples in a tight, low-variance band -- smooth and internally consistent, just offset from the true 40 centimeters.', 20, 2),

  ('mission-vec-sensors-11-o1-c1', 'orientation', 'Think about what happens to two errors pointing in different directions when they are combined, versus two errors pointing the same way.', 10, 1),
  ('mission-vec-sensors-11-o1-c1', 'solution', 'Different sensors tend to fail differently, so combining them lets errors cancel rather than stack -- unless every sensor happens to be wrong in the same direction at once.', 20, 2),
  ('mission-vec-sensors-11-o2-c1', 'orientation', 'Disagreement is a signal, not something to average away blindly.', 10, 1),
  ('mission-vec-sensors-11-o2-c1', 'solution', 'Treat the disagreement as a flag that at least one reading needs verification, rather than trusting either sensor without question.', 20, 2),

  ('mission-vec-sensors-12-o1-c1', 'orientation', 'Match the schematic''s sensor ID and conversion method against the reasoning from the distance-sensor and calibration missions.', 10, 1),
  ('mission-vec-sensors-12-o1-c1', 'solution', 'PROX-19, the infrared proximity sensor, is producing a confidently wrong number because its intensity-to-distance calibration was never corrected.', 20, 2),
  ('mission-vec-sensors-12-o2-c1', 'orientation', 'A smooth, consistent offset with no erratic behavior and no access history points away from damage or tampering.', 10, 1),
  ('mission-vec-sensors-12-o2-c1', 'solution', 'e1: twenty low-variance readings, all offset by roughly the same amount in the same direction, is the signature of a calibration drift, not a fault or an intrusion.', 20, 2),
  ('mission-vec-sensors-12-o3-c1', 'orientation', 'Think back to what actually corrects an offset, and what catches a future drift before it goes unnoticed again.', 10, 1),
  ('mission-vec-sensors-12-o3-c1', 'solution', 'Recalibrate against a known reference, and cross-check continuously against a second independent sensor -- either restores trust, and together they guard against it happening again.', 20, 2),
  ('mission-vec-sensors-12-o4-c1', 'orientation', 'Combine all three judgments into one sentence: which sensor, why it is wrong, and what fixes it.', 15, 1),
  ('mission-vec-sensors-12-o4-c1', 'solution', 'PROX-19 was never malicious and never broken -- it is a real proximity sensor that was never recalibrated after decades of thermal drift, reporting a plausible-looking but wrong distance with total, unearned confidence -- and a sensor that can be trusted, once calibrated and filtered, is only half the loop; the other half is whatever the door does in response, its actuators.', 25, 2);
